import { JsonEditor, Card, Badge } from "march/ui"

// oyun karakteri: JSON'u ağaçta değiştir, kart canlı güncellenir (ad, sınıf, seviye, can çubuğu)
type Hero = { name?: string; class?: string; level?: number; hp?: number }

export function HeroCard() {
  let $hero: unknown = { name: "Ayla", class: "Okçu", level: 7, hp: 64 }
  const $h = ($hero && typeof $hero === "object" ? $hero : {}) as Hero
  const $hp = Math.max(0, Math.min(100, Number($h.hp) || 0))
  return <div sx={{ flex: "col", gap: 2 }}>
    <Card m:theme="night">
      <div sx={{ flex: ["row", "center", "between"] }}>
        <span sx={{ text: "lg", color: "brand-gold" }}>{`${$h.name ?? "?"} · ${$h.class ?? "?"}`}</span>
        <Badge tone="info">{`Seviye ${$h.level ?? 0}`}</Badge>
      </div>
      <div role="meter" aria-label="Can" aria-valuenow={$hp} aria-valuemin={0} aria-valuemax={100}
        style={{ height: ".5rem", "margin-top": ".5rem", "border-radius": "1rem", width: `${$hp}%`, background: $hp > 30 ? "var(--m-success)" : "var(--m-danger)" }} />
    </Card>
    <JsonEditor bind:value={$hero} mode="tree" modes={["tree", "text"]} expand={1} rows={6} aria-label="Karakter" />
  </div>
}

import { JsonEditor, Button, toast } from "march/ui"

// özellik bayrakları ayarı: şema her bayrağın true / false olmasını ister; sorun varken Kaydet kapalı
const SCHEMA = {
  type: "object", required: ["flags"],
  properties: { flags: { type: "object", additionalProperties: { type: "boolean" } }, rollout: { type: "integer", minimum: 0, maximum: 100 } },
}
type Config = { flags?: Record<string, unknown>; rollout?: number }
// bozuk metin bir string olarak gelir: o da kaydedilemez
const isOk = (c: unknown): boolean => {
  if (!c || typeof c !== "object") return false
  const { flags = {}, rollout = 0 } = c as Config
  return Object.values(flags).every((f) => typeof f === "boolean") && Number.isInteger(rollout) && rollout >= 0 && rollout <= 100
}

export function FeatureFlags() {
  let $config: unknown = { flags: { darkMode: true, newSearch: false, betaExport: "yes" }, rollout: 25 }
  const $ok = isOk($config)
  return <div sx={{ flex: "col", gap: 2 }}>
    <JsonEditor bind:value={$config} schema={SCHEMA} mode="text" modes={["text", "tree"]} rows={9} aria-label="Ayarlar" />
    <div sx={{ flex: ["row", "end"] }}>
      <Button disabled={!$ok} on:click={() => toast("Ayarlar kaydedildi")}>{$ok ? "Kaydet" : "Önce sorunları düzeltin"}</Button>
    </div>
  </div>
}

import { JsonEditor, Card, Badge } from "march/ui"

// JsonEditor'ün bütün özellikleri: değer ve onChange, satır sayısı, ek denetim (validate), şema, biçim girintisi, Tab
// girintisi, ilk görünüm ve sunulan görünümler, ağacın açık düzeyi, Biçimlendir düğmesi, "geçerli" satırı, kendi
// metinleri (invalid ve more işlevleri dahil), salt okunur, sınıf
const SCHEMA = {
  type: "object", required: ["name", "port"],
  properties: { name: { type: "string" }, port: { type: "integer", minimum: 1024 }, tags: { type: "array", items: { type: "string" } } },
}

export function JsonEditorLab() {
  let $v: unknown = { name: "api", port: 80, tags: ["eu", 1] }
  let $changes = 0
  return <div sx={{ flex: "col", gap: 3 }}>
    <Badge tone="neutral">{`${$changes} değişiklik`}</Badge>
    <JsonEditor value={$v} onChange={(x) => { $v = x; $changes++ }} class="lab-json" aria-label="Sunucu ayarı"
      rows={8} schema={SCHEMA} indent={4} tabIndent mode="text" modes={["text", "tree"]} expand={1} format status
      validate={(x) => ((x as { name?: string })?.name === "root" ? "root adı ayrılmış" : null)}
      labels={{ text: "Kaynak", tree: "Ana hat", view: "Görünüm", treeName: "Ayar ağacı", fixFirst: "Önce JSON'u düzeltin",
        valid: "Sorun yok", format: "Toparla", invalid: (line, col) => `Bozuk JSON: ${line}. satır, ${col}. sütun`, more: (n) => `(+${n} sorun daha)` }} />
    <Card m:theme="night">
      <JsonEditor value={$v} mode="tree" modes={["tree"]} readonly format={false} status={false} tabIndent={false} expand={2} aria-label="Salt okunur ağaç" />
    </Card>
  </div>
}

import { test, expect, renderTest } from "march/testing"
import { JsonEditorLab } from "./JsonEditorLab.tsx"

// JsonEditorLab'in testleri: kaydedince Testler sekmesinde çalışır
test("şema sorunu ilk sorunla ve kendi 'more' metniyle yazılır", () => {
  const s = renderTest(() => <JsonEditorLab />)
  expect(s.sees("/port")).toBe(true)
  expect(s.sees("(+1 sorun daha)")).toBe(true)
  expect(s.find("Kaynak")?.getAttribute("role")).toBe("tab")
})

test("bozuk JSON kendi invalid metnini gösterir", async () => {
  const s = renderTest(() => <JsonEditorLab />)
  await s.type("Sunucu ayarı", '{ "name": ')
  expect(s.sees("Bozuk JSON")).toBe(true)
  expect(s.sees("1 değişiklik")).toBe(true)
})

test("düzeltilince validate çalışır, sonra Sorun yok", async () => {
  const s = renderTest(() => <JsonEditorLab />)
  await s.type("Sunucu ayarı", '{"name":"root","port":8080}')
  expect(s.sees("root adı ayrılmış")).toBe(true)
  await s.type("Sunucu ayarı", '{"name":"api","port":8080}')
  expect(s.sees("Sorun yok")).toBe(true)
})

test("Toparla 4 boşlukla biçimlendirir", async () => {
  const s = renderTest(() => <JsonEditorLab />)
  await s.type("Sunucu ayarı", '{"name":"api","port":8080}')
  await s.click("Toparla")
  expect((s.find("Sunucu ayarı") as HTMLTextAreaElement | null)?.value).toContain('\n    "port": 8080')
})
